-- ledger V1 (docs/specs/SPEC-ledger.md, "Modello dati e regole di accesso"): the
-- movements history. Purchases, redemptions and their corrections are only ever
-- inserted, by the ledger RPCs; a movement is never updated or deleted. The balance
-- of a customer is the sum of the points of all their movements.

-- Table ------------------------------------------------------------------------------
create table app.movements (
  id uuid primary key default gen_random_uuid(),
  -- generated by the app, so a resent operation is recognised
  operation_id uuid not null unique,
  customer_id uuid not null references app.customers (id) on delete restrict,
  kind text not null check (kind in ('purchase', 'redemption', 'correction')),
  -- purchase only: the amount spent, in integer cents
  amount_cents int null,
  points int not null,
  -- purchase only: the cents per point in force when it was recorded
  cents_per_point int null,
  -- catalogue redemption only; rewards are never deleted, and never cascade here
  reward_id uuid null references app.rewards (id),
  -- redemption only: the reward name or the free reward description, copied
  description text null,
  operator_id uuid not null references app.operators (id),
  created_at timestamptz not null default now(),
  -- correction only: the movement it cancels, at most once
  corrects_movement_id uuid null unique references app.movements (id),

  constraint movements_purchase_check check (
    -- a check passes on null, so every required value is tested with is not null
    kind <> 'purchase' or (
      amount_cents is not null
      and cents_per_point is not null
      and amount_cents between 1 and 9999999
      and cents_per_point > 0
      -- points are always rounded down with the ratio in force
      and points = amount_cents / cents_per_point
      and reward_id is null
      and description is null
      and corrects_movement_id is null
    )
  ),
  constraint movements_redemption_check check (
    kind <> 'redemption' or (
      amount_cents is null
      and cents_per_point is null
      and points between -99999 and -1
      and description is not null
      and description = btrim(description)
      and length(description) between 1 and 80
      and corrects_movement_id is null
    )
  ),
  constraint movements_correction_check check (
    kind <> 'correction' or (
      amount_cents is null
      and cents_per_point is null
      and reward_id is null
      and description is null
      and corrects_movement_id is not null
      and corrects_movement_id <> id
    )
  )
);

comment on table app.movements is
  'Points history. Append-only: rows are inserted by the ledger RPCs and never updated or deleted; '
  'a cancellation is a correction of opposite sign. No personal data of the customer is copied here.';

create index movements_customer_created_idx on app.movements (customer_id, created_at desc);
create index movements_created_idx on app.movements (created_at, id);
create index movements_operator_idx on app.movements (operator_id);
create index movements_reward_idx on app.movements (reward_id);

-- Rows are written only through the ledger RPCs (security definer).
revoke insert, update, delete, truncate on app.movements from authenticated, anon;

create policy movements_select_for_active_operators
  on app.movements
  for select
  to authenticated
  using ((select private.is_active_operator()));

-- Append-only, even for postgres ------------------------------------------------------
-- A guard against mistakes (the SQL Editor runs as postgres), not against the owner
-- of the database: a superuser can still drop these triggers.
create function private.movements_are_append_only()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  raise exception 'app.movements is append-only: movements are never updated or deleted'
    using errcode = '42501',
          hint = 'Cancel a movement with app.cancel_movement, which inserts a correction.';
end;
$$;

revoke execute on function private.movements_are_append_only() from public, anon, authenticated;

create trigger movements_no_update_or_delete
  before update or delete on app.movements
  for each row execute function private.movements_are_append_only();

create trigger movements_no_truncate
  before truncate on app.movements
  for each statement execute function private.movements_are_append_only();

-- customer_balance -------------------------------------------------------------------
-- The only definition of the balance in the database: the sum of the points of
-- every movement, cancelled ones and corrections included.
create function private.customer_balance(p_customer_id uuid)
returns int
language sql
stable
set search_path = ''
as $$
  select coalesce(sum(m.points), 0)::int from app.movements m where m.customer_id = p_customer_id;
$$;

revoke execute on function private.customer_balance(uuid) from public, anon, authenticated;

-- movement_history -----------------------------------------------------------------------
-- Movements with the operator's name, who cancelled them and when (from the correction
-- pointing at them) and, for a correction, the kind and time of the movement it
-- cancelled. security_invoker: the reader's RLS applies.
create view app.movement_history
with (security_invoker = true)
as
select
  m.id,
  m.operation_id,
  m.customer_id,
  m.kind,
  m.amount_cents,
  m.points,
  m.cents_per_point,
  m.reward_id,
  m.description,
  m.operator_id,
  o.name as operator_name,
  m.created_at,
  m.corrects_movement_id,
  c.operator_id as cancelled_by_id,
  c.created_at as cancelled_at,
  t.kind as corrected_kind,
  t.created_at as corrected_created_at
from app.movements m
join app.operators o on o.id = m.operator_id
left join app.movements c on c.corrects_movement_id = m.id
left join app.movements t on t.id = m.corrects_movement_id;

-- The default privileges of app grant writes on new relations: the view is read-only.
revoke all on app.movement_history from public, anon, authenticated;
grant select on app.movement_history to authenticated;

-- ledger_result ------------------------------------------------------------------------------
-- What every ledger write RPC returns: the movement and the customer's current balance.
create type app.ledger_result as (
  movement app.movement_history,
  balance int
);

-- acting_operator_id -------------------------------------------------------------
-- Common body shared word for word with settings, customers and rewards
-- (docs/specs/cross-review.md §2.1). tablet-kiosk redefines it later.
create or replace function private.acting_operator_id()
returns uuid
language sql
stable
security definer
set search_path = ''
as $$
  select private.current_operator_id();
$$;

revoke execute on function private.acting_operator_id() from public, anon, authenticated;

-- ledger_result_for ------------------------------------------------------------------------
-- A movement as the write RPCs return it: its history row and the current balance of
-- its customer (a replay too returns the current balance, Open Question 6).
create function private.ledger_result_for(p_movement_id uuid)
returns app.ledger_result
language plpgsql
stable
set search_path = ''
as $$
declare
  v_movement app.movement_history;
begin
  select h.* into strict v_movement from app.movement_history h where h.id = p_movement_id;
  return (v_movement, private.customer_balance(v_movement.customer_id))::app.ledger_result;
end;
$$;

revoke execute on function private.ledger_result_for(uuid) from public, anon, authenticated;

-- lock_customer_for_ledger -----------------------------------------------------------------
-- Step 2 of every ledger write: locks the customer's row until the end of the
-- transaction, so writes on the same customer (and their balance checks) run one
-- after the other. A customer that does not exist or was anonymized is EC006.
create function private.lock_customer_for_ledger(p_customer_id uuid)
returns void
language plpgsql
set search_path = ''
as $$
declare
  v_anonymized_at timestamptz;
begin
  select c.anonymized_at into v_anonymized_at
  from app.customers c
  where c.id = p_customer_id
  for update;
  if not found or v_anonymized_at is not null then
    raise exception 'customer unavailable' using errcode = 'EC006';
  end if;
end;
$$;

revoke execute on function private.lock_customer_for_ledger(uuid) from public, anon, authenticated;

-- record_purchase ------------------------------------------------------------------------------
-- Records a purchase of p_amount_cents: points = amount / cents_per_point in force,
-- rounded down; the ratio is saved on the movement. Resending the same operation_id
-- returns the first movement.
create function app.record_purchase(p_operation_id uuid, p_customer_id uuid, p_amount_cents int)
returns app.ledger_result
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_operator uuid;
  v_existing app.movements;
  v_cents_per_point int;
  v_id uuid;
begin
  -- (1) who records it
  v_operator := private.acting_operator_id();
  if v_operator is null then
    raise exception 'No acting operator for this write' using errcode = '42501';
  end if;

  -- (2) one write at a time per customer
  perform private.lock_customer_for_ledger(p_customer_id);

  -- (3) after the lock, so a concurrent first request has committed: replay or conflict
  select * into v_existing from app.movements where operation_id = p_operation_id;
  if found then
    if v_existing.kind = 'purchase'
       and v_existing.customer_id = p_customer_id
       and v_existing.amount_cents = p_amount_cents then
      return private.ledger_result_for(v_existing.id);
    end if;
    raise exception 'operation_id already used for another operation' using errcode = 'EC007';
  end if;

  -- (4) validate, compute, insert
  if p_operation_id is null then
    raise exception 'operation_id is required' using errcode = '22023';
  end if;
  if p_amount_cents is null or p_amount_cents not between 1 and 9999999 then
    raise exception 'amount_cents must be between 1 and 9999999, got %', p_amount_cents
      using errcode = '22023';
  end if;

  select s.cents_per_point into strict v_cents_per_point from app.settings s;

  begin
    insert into app.movements
      (operation_id, customer_id, kind, amount_cents, points, cents_per_point, operator_id)
    values
      (p_operation_id, p_customer_id, 'purchase', p_amount_cents,
       p_amount_cents / v_cents_per_point, v_cents_per_point, v_operator)
    returning id into v_id;
  exception when unique_violation then
    -- Only possible when a concurrent request used the same operation_id on another
    -- customer (same customer: the lock serialised them and step 3 saw it).
    raise exception 'operation_id already used for another operation' using errcode = 'EC007';
  end;

  return private.ledger_result_for(v_id);
end;
$$;

-- Explicit grants: never rely on the default privileges.
revoke execute on function app.record_purchase(uuid, uuid, int) from public, anon;
grant execute on function app.record_purchase(uuid, uuid, int) to authenticated;

-- redeem_reward ------------------------------------------------------------------------------
-- Redeems a reward of the catalogue (SPEC-rewards.md, "Interfaccia verso ledger"): the
-- reward is read here, never trusted from the app; an inactive or unknown one is EC005.
-- The movement saves its current points (negative) and name, so later changes to the
-- reward never alter the history. The balance may never go below zero (EC001), checked
-- after the customer's lock so two concurrent redemptions cannot spend the same points.
create function app.redeem_reward(p_operation_id uuid, p_customer_id uuid, p_reward_id uuid)
returns app.ledger_result
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_operator uuid;
  v_existing app.movements;
  v_reward app.rewards;
  v_id uuid;
begin
  -- (1) who records it
  v_operator := private.acting_operator_id();
  if v_operator is null then
    raise exception 'No acting operator for this write' using errcode = '42501';
  end if;

  -- (2) one write at a time per customer
  perform private.lock_customer_for_ledger(p_customer_id);

  -- (3) replay or conflict; a replay returns the first movement even if the reward
  -- changed or was deactivated since
  select * into v_existing from app.movements where operation_id = p_operation_id;
  if found then
    if v_existing.kind = 'redemption'
       and v_existing.customer_id = p_customer_id
       and v_existing.reward_id = p_reward_id then
      return private.ledger_result_for(v_existing.id);
    end if;
    raise exception 'operation_id already used for another operation' using errcode = 'EC007';
  end if;

  -- (4) validate, read the reward, check the balance, insert
  if p_operation_id is null then
    raise exception 'operation_id is required' using errcode = '22023';
  end if;

  -- for share: a concurrent change of the reward waits until this redemption commits
  select * into v_reward from app.rewards r where r.id = p_reward_id for share;
  if not found or not v_reward.active then
    raise exception 'reward unavailable' using errcode = 'EC005';
  end if;

  if private.customer_balance(p_customer_id) - v_reward.points < 0 then
    raise exception 'insufficient balance' using errcode = 'EC001';
  end if;

  begin
    insert into app.movements
      (operation_id, customer_id, kind, points, reward_id, description, operator_id)
    values
      (p_operation_id, p_customer_id, 'redemption', -v_reward.points, v_reward.id, v_reward.name,
       v_operator)
    returning id into v_id;
  exception when unique_violation then
    raise exception 'operation_id already used for another operation' using errcode = 'EC007';
  end;

  return private.ledger_result_for(v_id);
end;
$$;

revoke execute on function app.redeem_reward(uuid, uuid, uuid) from public, anon;
grant execute on function app.redeem_reward(uuid, uuid, uuid) to authenticated;

-- redeem_free_reward ---------------------------------------------------------------------------
-- Redeems a reward outside the catalogue: a description of 1..80 characters after
-- trimming outer (Unicode) spaces and 1..99999 points, otherwise 22023. Same lock,
-- replay and balance rules as redeem_reward.
create function app.redeem_free_reward(
  p_operation_id uuid, p_customer_id uuid, p_description text, p_points int
)
returns app.ledger_result
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_operator uuid;
  v_existing app.movements;
  v_description text := private.trim_spaces(p_description);
  v_id uuid;
begin
  -- (1) who records it
  v_operator := private.acting_operator_id();
  if v_operator is null then
    raise exception 'No acting operator for this write' using errcode = '42501';
  end if;

  -- (2) one write at a time per customer
  perform private.lock_customer_for_ledger(p_customer_id);

  -- (3) replay or conflict
  select * into v_existing from app.movements where operation_id = p_operation_id;
  if found then
    if v_existing.kind = 'redemption'
       and v_existing.reward_id is null
       and v_existing.customer_id = p_customer_id
       and v_existing.description = v_description
       and v_existing.points = -p_points then
      return private.ledger_result_for(v_existing.id);
    end if;
    raise exception 'operation_id already used for another operation' using errcode = 'EC007';
  end if;

  -- (4) validate, check the balance, insert
  if p_operation_id is null then
    raise exception 'operation_id is required' using errcode = '22023';
  end if;
  if v_description is null or length(v_description) not between 1 and 80 then
    raise exception 'description must be 1 to 80 characters' using errcode = '22023';
  end if;
  if p_points is null or p_points not between 1 and 99999 then
    raise exception 'points must be between 1 and 99999, got %', p_points using errcode = '22023';
  end if;

  if private.customer_balance(p_customer_id) - p_points < 0 then
    raise exception 'insufficient balance' using errcode = 'EC001';
  end if;

  begin
    insert into app.movements (operation_id, customer_id, kind, points, description, operator_id)
    values (p_operation_id, p_customer_id, 'redemption', -p_points, v_description, v_operator)
    returning id into v_id;
  exception when unique_violation then
    raise exception 'operation_id already used for another operation' using errcode = 'EC007';
  end;

  return private.ledger_result_for(v_id);
end;
$$;

revoke execute on function app.redeem_free_reward(uuid, uuid, text, int) from public, anon;
grant execute on function app.redeem_free_reward(uuid, uuid, text, int) to authenticated;
